func NewLogger(output io.Writer, config LogConfig, bus *EventBus, attrs ...slog.Attr) (*slog.Logger, error) {
	config, level, err := ParseLogConfig(config.Format, config.Level)
	if err != nil {
		return nil, err
	}
	if journalStream() {
		output = journalWriter{next: output}
	}
	options := &slog.HandlerOptions{Level: level, ReplaceAttr: utcTime}
	var handler slog.Handler
	if config.Format == "logfmt" {
		handler = slog.NewTextHandler(output, options)
	} else {
		handler = slog.NewJSONHandler(output, options)
	}
	if bus != nil {
		handler = &EventTee{next: handler, bus: bus, counters: newLogCounters(), repeats: newEventRepeats()}
	}
	handler = &redactingHandler{next: handler}
	if len(attrs) > 0 {
		handler = handler.WithAttrs(attrs)
	}
	return slog.New(handler), nil
}

func utcTime(groups []string, attr slog.Attr) slog.Attr {
	if attr.Key == slog.TimeKey && len(groups) == 0 && attr.Value.Kind() == slog.KindTime {
		attr.Value = slog.TimeValue(attr.Value.Time().UTC())
	}
	return attr
}

func (w journalWriter) Write(record []byte) (int, error) {
	if _, err := w.next.Write(append([]byte(journalPriority(record)), record...)); err != nil {
		return 0, err
	}
	return len(record), nil
}

func journalPriority(record []byte) string {
	best, prefix := len(record), "<5>"
	for _, priority := range journalPriorities {
		for _, marker := range []string{`"level":"` + priority.level + `"`, "level=" + priority.level + " "} {
			if at := bytes.Index(record, []byte(marker)); at >= 0 && at < best {
				best, prefix = at, priority.prefix
			}
		}
	}
	return prefix
}

func (tee *EventTee) Handle(ctx context.Context, record slog.Record) error {
	if record.Level >= slog.LevelWarn || tee.marked(record) {
		event := eventFromRecord(record, tee.eventScope(), tee.groups)
		if tee.repeats.admit(event, record.Time) {
			tee.bus.Publish(event)
		}
	}
	if !tee.next.Enabled(ctx, record.Level) {
		return nil
	}
	tee.counters.count(record.Level)
	return tee.next.Handle(ctx, record)
}

func (tee *EventTee) eventScope() []slog.Attr {
	for _, attr := range slices.Backward(tee.scoped) {
		if attr.Key == ComponentKey {
			return []slog.Attr{attr}
		}
	}
	return nil
}

func (tee *EventTee) marked(record slog.Record) bool {
	marked := false
	record.Attrs(func(attr slog.Attr) bool {
		if attr.Key == EventKey && attr.Value.Kind() == slog.KindBool && attr.Value.Bool() {
			marked = true
			return false
		}
		return true
	})
	return marked
}

func (tee *EventTee) WithAttrs(attrs []slog.Attr) slog.Handler {
	clone := *tee
	clone.next = tee.next.WithAttrs(attrs)
	if len(tee.groups) == 0 {
		clone.scoped = append(slices.Clone(tee.scoped), attrs...)
	}
	return &clone
}

func (tee *EventTee) WithGroup(name string) slog.Handler {
	clone := *tee
	clone.next = tee.next.WithGroup(name)
	clone.groups = append(slices.Clone(tee.groups), name)
	return &clone
}

func (repeats *eventRepeats) admit(event Event, now time.Time) bool {
	if repeats == nil {
		return true
	}
	if now.IsZero() {
		now = time.Now()
	}
	key := eventRepeatKey(event)
	repeats.mu.Lock()
	defer repeats.mu.Unlock()
	if last, ok := repeats.last[key]; ok && now.Sub(last) >= 0 && now.Sub(last) < eventRepeatWindow {
		repeats.suppressed.Add(1)
		return false
	}
	if len(repeats.last) >= maxEventRepeats {
		for existing, at := range repeats.last {
			if now.Sub(at) >= eventRepeatWindow {
				delete(repeats.last, existing)
			}
		}
		if len(repeats.last) >= maxEventRepeats {
			clear(repeats.last)
		}
	}
	repeats.last[key] = now
	return true
}

func eventRepeatKey(event Event) string {
	var key strings.Builder
	key.WriteString(event.Level)
	key.WriteByte(0)
	key.WriteString(event.Component)
	key.WriteByte(0)
	key.WriteString(event.Message)
	for _, name := range slices.Sorted(maps.Keys(event.Attrs)) {
		key.WriteByte(0)
		key.WriteString(name)
		key.WriteByte('=')
		key.WriteString(event.Attrs[name])
	}
	return key.String()
}

func (h *redactingHandler) Handle(ctx context.Context, record slog.Record) error {
	s := logSanitizer{remaining: maxLogAttrs - 1 - h.used, truncated: h.truncated}
	if h.component.Key != "" {
		s.remaining--
	}
	clean := slog.NewRecord(record.Time, record.Level, s.text(record.Message, maxLogMessageBytes), record.PC)
	// The trace ID follows the static attributes and precedes the call's own.
	if trace := TraceID(ctx); trace != "" {
		s.remaining--
		clean.AddAttrs(slog.String(TraceIDKey, trace))
	}
	// Preserve selection and component even when ordinary attributes exhaust
	// the budget. This scan does not resolve or format application values.
	var event, component slog.Attr
	eventIndex, componentIndex := -1, -1
	index := 0
	record.Attrs(func(a slog.Attr) bool {
		if a.Key == EventKey && a.Value.Kind() == slog.KindBool {
			if event.Key == "" || !event.Value.Bool() {
				event = a
				eventIndex = index
			}
		}
		if a.Key == ComponentKey {
			component = a
			componentIndex = index
		}
		index++
		return true
	})
	// Reserve metadata capacity, but emit it in its original position so an
	// inline group and a root component keep their last-value-wins ordering.
	for _, a := range []*slog.Attr{&event, &component} {
		if a.Key != "" {
			*a, _ = s.attr(*a, h.depth, h.sensitive)
		}
	}
	index = -1
	record.Attrs(func(a slog.Attr) bool {
		index++
		if index == eventIndex {
			if event.Key != "" {
				clean.AddAttrs(event)
			}
			return true
		}
		if index == componentIndex {
			if component.Key != "" {
				clean.AddAttrs(component)
			}
			return true
		}
		if a.Key == ComponentKey || (a.Key == EventKey && eventIndex >= 0) {
			return true
		}
		if h.blocked || s.remaining <= 0 {
			s.truncated = true
			return true
		}
		if prepared, ok := s.attr(a, h.depth, h.sensitive); ok {
			clean.AddAttrs(prepared)
		}
		return true
	})
	if s.truncated {
		clean.AddAttrs(slog.Bool(logTruncatedKey, true))
	}
	return h.next.Handle(ctx, clean)
}

func (h *redactingHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	clone := *h
	s := logSanitizer{remaining: maxLogAttrs - 4 - h.used, truncated: h.truncated}
	componentIndex := -1
	// A root scoped component has its own slot, so adding it to an already
	// full scope still preserves component attribution without growing scope.
	if h.depth == 0 && !h.blocked {
		var component slog.Attr
		for i, a := range attrs {
			if a.Key == ComponentKey {
				component = a
				componentIndex = i
			}
		}
		if component.Key != "" {
			metadata := logSanitizer{remaining: 1}
			clone.component, _ = metadata.attr(component, maxLogDepth, false)
			s.truncated = s.truncated || metadata.truncated
		}
	}
	var clean []slog.Attr
	componentPosition := -1
	for i, a := range attrs {
		if h.depth == 0 && !h.blocked && a.Key == ComponentKey {
			if i == componentIndex {
				componentPosition = len(clean)
			}
			continue
		}
		if h.blocked || s.remaining <= 0 {
			s.truncated = true
			break
		}
		if prepared, ok := s.attr(a, h.depth, h.sensitive); ok {
			clean = append(clean, prepared)
		}
	}
	clone.used += maxLogAttrs - 4 - h.used - s.remaining
	clone.truncated = s.truncated
	if componentIndex >= 0 {
		clone.scopes = nil
		for _, scope := range h.scopes {
			if !scope.component {
				clone.scopes = append(clone.scopes, scope)
			}
		}
		if componentPosition < 0 {
			componentPosition = len(clean)
		}
		if componentPosition > 0 {
			clone.scopes = append(clone.scopes, logScope{attrs: clean[:componentPosition]})
		}
		clone.scopes = append(clone.scopes, logScope{component: true})
		if componentPosition < len(clean) {
			clone.scopes = append(clone.scopes, logScope{attrs: clean[componentPosition:]})
		}
	} else if len(clean) > 0 {
		clone.scopes = appendScope(h.scopes, logScope{attrs: clean})
	}
	clone.rebuild()
	return &clone
}

func (h *redactingHandler) WithGroup(name string) slog.Handler {
	if name == "" {
		return h
	}
	clone := *h
	clone.sensitive = h.sensitive || sensitiveLogKey(name)
	if h.blocked || h.depth >= maxLogDepth || h.used >= maxLogAttrs-4 {
		clone.blocked, clone.truncated = true, true
		return &clone
	}
	s := logSanitizer{}
	clone.scopes = appendScope(h.scopes, logScope{group: s.text(name, maxLogNameBytes)})
	clone.depth++
	clone.used++
	clone.truncated = h.truncated || s.truncated
	clone.rebuild()
	return &clone
}

func appendScope(scopes []logScope, scope logScope) []logScope {
	return append(append([]logScope(nil), scopes...), scope)
}

// Rebuild only on With operations. Keeping bounded prepared scope lets a
// replacement component discard the old value instead of accumulating attrs.
func (h *redactingHandler) rebuild() {
	if h.base == nil {
		h.base = h.next
	}
	h.next = h.base
	for _, scope := range h.scopes {
		if scope.component {
			h.next = h.next.WithAttrs([]slog.Attr{h.component})
		} else if scope.group != "" {
			h.next = h.next.WithGroup(scope.group)
		} else {
			h.next = h.next.WithAttrs(scope.attrs)
		}
	}
}

func (s *logSanitizer) attr(a slog.Attr, depth int, sensitive bool) (slog.Attr, bool) {
	if s.remaining <= 0 {
		s.truncated = true
		return slog.Attr{}, false
	}
	s.remaining--
	if a.Key == "" && a.Value.Kind() == slog.KindAny && a.Value.Any() == nil {
		return slog.Attr{}, false
	}
	key := s.text(a.Key, maxLogNameBytes)
	// Never invoke a valuer/error/stringer for a known sensitive field.
	if (sensitive || sensitiveLogKey(a.Key)) && !(a.Key == EventKey && a.Value.Kind() == slog.KindBool) {
		return slog.String(key, redactedLogValue), true
	}
	value := s.resolve(a.Value)
	if value.Kind() == slog.KindGroup {
		if depth >= maxLogDepth {
			s.truncated = true
			return slog.String(key, omittedLogValue), true
		}
		var children []slog.Attr
		for _, child := range value.Group() {
			if s.remaining <= 0 {
				s.truncated = true
				break
			}
			if prepared, ok := s.attr(child, depth+1, sensitive); ok {
				children = append(children, prepared)
			}
		}
		return slog.Attr{Key: key, Value: slog.GroupValue(children...)}, true
	}
	if value.Kind() == slog.KindTime {
		// Event values expose zone names, unlike RFC3339 log output.
		at := value.Time()
		zone, offset := at.Zone()
		value = slog.TimeValue(at.In(time.FixedZone(s.text(zone, maxLogNameBytes), offset)))
	} else if value.Kind() == slog.KindString {
		value = slog.StringValue(s.text(value.String(), maxLogValueBytes))
	} else if value.Kind() == slog.KindAny {
		value = s.anyValue(value.Any(), depth)
	}
	return slog.Attr{Key: key, Value: value}, true
}

// Resolve one step at a time: slog.Value.Resolve can repeatedly invoke a
// valuer, and a valuer may return a group containing itself.
func (s *logSanitizer) resolve(value slog.Value) (resolved slog.Value) {
	defer func() {
		if recover() != nil {
			s.truncated = true
			resolved = slog.StringValue(omittedLogValue)
		}
	}()
	for range maxLogDepth {
		if value.Kind() != slog.KindLogValuer {
			return value
		}
		value = value.LogValuer().LogValue()
	}
	if value.Kind() == slog.KindLogValuer {
		s.truncated = true
		return slog.StringValue(omittedLogValue)
	}
	return value
}

func (s *logSanitizer) anyValue(value any, depth int) (result slog.Value) {
	defer func() {
		if recover() != nil {
			s.truncated = true
			result = slog.StringValue(omittedLogValue)
		}
	}()
	switch v := value.(type) {
	case nil:
		return slog.AnyValue(nil)
	case error:
		return slog.StringValue(s.text(v.Error(), maxLogValueBytes))
	case fmt.Stringer:
		return slog.StringValue(s.text(v.String(), maxLogValueBytes))
	}
	// Snapshot containers with a shared node/depth budget, never fmt or JSON
	// marshal the application's object (which could recurse or run custom code).
	frozen := s.snapshot(reflect.ValueOf(value), depth)
	encoded, err := json.Marshal(frozen)
	if err != nil {
		s.truncated = true
		return slog.StringValue(omittedLogValue)
	}
	return slog.StringValue(s.text(string(encoded), maxLogValueBytes))
}

func (s *logSanitizer) snapshot(value reflect.Value, depth int) any {
	if !value.IsValid() {
		return nil
	}
	if s.remaining <= 0 {
		s.truncated = true
		return omittedLogValue
	}
	s.remaining--
	if depth >= maxLogDepth {
		s.truncated = true
		return omittedLogValue
	}
	switch value.Kind() {
	case reflect.Interface, reflect.Pointer:
		if value.IsNil() {
			return nil
		}
		return s.snapshot(value.Elem(), depth+1)
	case reflect.String:
		return s.text(value.String(), maxLogValueBytes)
	case reflect.Bool:
		return value.Bool()
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return value.Int()
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return value.Uint()
	case reflect.Float32, reflect.Float64:
		return value.Float()
	case reflect.Map:
		if value.Type().Key().Kind() != reflect.String {
			break
		}
		if value.Len() > s.remaining {
			s.truncated = true
			return omittedLogValue
		}
		// Collect only bounded maps; sorted traversal makes nested clipping stable.
		keys := value.MapKeys()
		for _, key := range keys {
			if len(key.String()) > maxLogScanBytes {
				s.truncated = true
				return omittedLogValue
			}
		}
		slices.SortFunc(keys, func(a, b reflect.Value) int {
			return strings.Compare(a.String(), b.String())
		})
		frozen := map[string]any{}
		for _, mapKey := range keys {
			if s.remaining <= 0 {
				s.truncated = true
				break
			}
			key := mapKey.String()
			if sensitiveLogKey(key) {
				s.remaining--
				frozen[s.text(key, maxLogNameBytes)] = redactedLogValue
			} else {
				frozen[s.text(key, maxLogNameBytes)] = s.snapshot(value.MapIndex(mapKey), depth+1)
			}
		}
		return frozen
	case reflect.Slice, reflect.Array:
		if value.Kind() == reflect.Slice && value.Type().Elem().Kind() == reflect.Uint8 {
			if value.Len() > maxLogScanBytes {
				s.truncated = true
				return omittedLogValue
			}
			return s.text(string(value.Bytes()), maxLogValueBytes)
		}
		frozen := []any{}
		for i := 0; i < value.Len(); i++ {
			if s.remaining <= 0 {
				s.truncated = true
				break
			}
			frozen = append(frozen, s.snapshot(value.Index(i), depth+1))
		}
		return frozen
	}
	s.truncated = true
	return omittedLogValue
}

func sensitiveLogKey(key string) bool {
	if len(key) > maxLogScanBytes {
		return true
	}
	var normalized strings.Builder
	for _, r := range key {
		if r >= 'A' && r <= 'Z' {
			r += 'a' - 'A'
		}
		if r >= 'a' && r <= 'z' || r >= '0' && r <= '9' {
			normalized.WriteRune(r)
		}
	}
	name := normalized.String()
	for _, sensitive := range []string{"authorization", "cookie", "session", "password", "passwd", "token", "secret", "seed", "privatekey", "credential", "accesskey", "apikey"} {
		if strings.Contains(name, sensitive) {
			return true
		}
	}
	return false
}

func (s *logSanitizer) text(value string, limit int) string {
	// Fail closed rather than cutting an unfinished credential at the scan
	// boundary. All regex work is RE2 and limited to this input size.
	if len(value) > maxLogScanBytes {
		s.truncated = true
		return omittedLogValue
	}
	if !utf8.ValidString(value) {
		s.truncated = true
		value = strings.ToValidUTF8(value, "�")
	}
	value = logPEM.ReplaceAllString(value, redactedLogValue)
	value = logURL.ReplaceAllStringFunc(value, func(raw string) string {
		parsed, err := url.Parse(raw)
		if err != nil {
			return redactedLogValue
		}
		if parsed.User != nil {
			parsed.User = url.User(redactedLogValue)
		}
		return parsed.String()
	})
	value = logQuery.ReplaceAllStringFunc(value, func(raw string) string {
		key, _, _ := strings.Cut(raw[1:], "=")
		decoded, err := url.QueryUnescape(key)
		if err != nil || sensitiveLogKey(decoded) {
			return raw[:1] + key + "=" + redactedLogValue
		}
		return raw
	})
	value = logBearer.ReplaceAllString(value, "Bearer "+redactedLogValue)
	value = logJWT.ReplaceAllStringFunc(value, func(raw string) string {
		header, _, _ := strings.Cut(raw, ".")
		decoded, err := base64.RawURLEncoding.DecodeString(header)
		if err == nil && strings.HasPrefix(strings.TrimSpace(string(decoded)), "{") && json.Valid(decoded) {
			return redactedLogValue
		}
		return raw
	})
	value = logSeed.ReplaceAllString(value, redactedLogValue)
	if len(value) > limit {
		s.truncated = true
		cut := limit - len("...")
		for cut > 0 && !utf8.RuneStart(value[cut]) {
			cut--
		}
		value = value[:cut] + "..."
	}
	// Clone even short substrings: scoped strings must not pin large input buffers.
	return strings.Clone(value)
}

func NewEventBus(capacity int) *EventBus {
	if capacity <= 0 {
		capacity = DefaultEventCapacity
	}
	return &EventBus{ring: make([]Event, capacity), subscribers: map[*eventSubscriber]struct{}{}}
}

func (bus *EventBus) Publish(event Event) Event {
	if bus == nil {
		return event
	}
	if event.Time.IsZero() {
		event.Time = time.Now().UTC()
	}
	bus.mu.Lock()
	bus.initLocked()
	bus.sequence++
	event.Sequence = bus.sequence
	index := (bus.start + bus.size) % len(bus.ring)
	if bus.size == len(bus.ring) {
		bus.start = (bus.start + 1) % len(bus.ring)
	} else {
		bus.size++
	}
	bus.ring[index] = event
	for subscriber := range bus.subscribers {
		select {
		case subscriber.events <- event:
		default:
			bus.dropped.Add(1)
		}
	}
	bus.mu.Unlock()
	bus.published.Add(1)
	return event
}

func (bus *EventBus) Recent(limit int) []Event {
	return bus.Since(0, limit)
}

// Since returns up to limit events with a sequence greater than after, oldest
// first, keeping the newest when more are available. A dashboard reconnecting
// with its last seen sequence uses it to resume without duplicates.
func (bus *EventBus) Since(after uint64, limit int) []Event {
	if bus == nil {
		return nil
	}
	bus.mu.Lock()
	defer bus.mu.Unlock()
	events := make([]Event, 0, bus.size)
	for offset := range bus.size {
		event := bus.ring[(bus.start+offset)%len(bus.ring)]
		if event.Sequence > after {
			events = append(events, event)
		}
	}
	if limit > 0 && len(events) > limit {
		events = events[len(events)-limit:]
	}
	return events
}

func eventFromRecord(record slog.Record, scoped []slog.Attr, groups []string) Event {
	event := Event{Time: record.Time.UTC(), Level: record.Level.String(), Message: record.Message}
	attrs := make(map[string]string, record.NumAttrs()+len(scoped))
	add := func(attr slog.Attr) {
		prefix := ""
		for _, group := range groups {
			prefix += group + "."
		}
		flattenAttr(attrs, prefix, attr)
	}
	for _, attr := range scoped {
		add(attr)
	}
	record.Attrs(func(attr slog.Attr) bool {
		add(attr)
		return true
	})
	if component, ok := attrs[ComponentKey]; ok {
		event.Component = component
		delete(attrs, ComponentKey)
	}
	delete(attrs, EventKey)
	// A trace is new on every pass, so keeping its ID would defeat the repeat window.
	delete(attrs, TraceIDKey)
	if len(attrs) > 0 {
		event.Attrs = attrs
	}
	return event
}

func flattenAttr(attrs map[string]string, prefix string, attr slog.Attr) {
	attr.Value = attr.Value.Resolve()
	if attr.Equal(slog.Attr{}) || len(attrs) >= maxEventAttrs {
		return
	}
	if attr.Value.Kind() == slog.KindGroup {
		nested := prefix
		if attr.Key != "" {
			nested += attr.Key + "."
		}
		for _, child := range attr.Value.Group() {
			flattenAttr(attrs, nested, child)
		}
		return
	}
	value := attr.Value.String()
	if len(value) > maxEventAttrBytes {
		// Cut on a rune boundary so a long non-ASCII value never carries a
		// split UTF-8 sequence into the event.
		cut := maxEventAttrBytes
		for cut > 0 && !utf8.RuneStart(value[cut]) {
			cut--
		}
		value = value[:cut] + "..."
	}
	attrs[prefix+attr.Key] = value
}
